# Grammaire espagnole, expliquée dans les autres langues d'interface.
T = {
'prononciation': {
 'de': ('Aussprache und Akzentzeichen', "Spanisch wird gelesen, wie es geschrieben wird. Fünf reine Vokale: a, e, i, o, u.\nc vor e / i und z: in Spanien wie englisches „th“, in Lateinamerika wie „s“ (cielo, zapato). j sowie g vor e / i: rauer Laut wie „ch“ in „Bach“ (jamón, gente). g vor a, o, u: hartes g; in gue, gui ist das u stumm.\nh ist stumm (hola). ll und y: wie „j“ in „ja“. ñ: wie „nj“ (año). b und v klingen gleich.\nEinfaches r: ein Zungenschlag; rr und r am Wortanfang: gerollt (pero / perro).\nBetonung: auf der vorletzten Silbe, wenn das Wort auf Vokal, n oder s endet (casa, hablan); sonst auf der letzten (hablar, ciudad). Der Akzent markiert Ausnahmen (café, árbol) und unterscheidet Wörter (sí / si, él / el).", ['Der Hund frisst Schinken.', 'Die Stadt ist groß.']),
 'it': ('Pronuncia e accento scritto', "Lo spagnolo si legge come si scrive. Cinque vocali pure: a, e, i, o, u.\nc davanti a e / i e z: come il «th» inglese in Spagna, come «s» in America Latina (cielo, zapato). j, e g davanti a e / i: suono gutturale, come il «ch» tedesco di Bach (jamón, gente). g davanti ad a, o, u: g dura; in gue, gui la u non si pronuncia.\nh è muta (hola). ll e y: come la «i» di «ieri». ñ: come «gn» (año). b e v si pronunciano uguali.\nr semplice: un colpo di lingua; rr e r iniziale: vibrata (pero / perro).\nAccento: sulla penultima sillaba se la parola finisce in vocale, n o s (casa, hablan); altrimenti sull'ultima (hablar, ciudad). L'accento scritto segnala le eccezioni (café, árbol) e distingue le parole (sí / si, él / el).", ['Il cane mangia prosciutto.', 'La città è grande.']),
 'pt': ('Pronúncia e acento gráfico', "O espanhol lê-se como se escreve. Cinco vogais puras: a, e, i, o, u (nunca nasais).\nc antes de e / i e z: como o «th» inglês na Espanha, como «s» na América Latina (cielo, zapato). j, e g antes de e / i: som gutural, como o «r» carioca (jamón, gente). g antes de a, o, u: g duro; em gue, gui o u é mudo.\nh é mudo (hola). ll e y: como «i» de «iate». ñ: como «nh» (año). b e v soam igual.\nr simples: uma batida de língua; rr e r inicial: vibrante (pero / perro).\nAcento tônico: penúltima sílaba se a palavra termina em vogal, n ou s (casa, hablan); senão a última (hablar, ciudad). O acento gráfico marca exceções (café, árbol) e distingue palavras (sí / si, él / el).", ['O cachorro come presunto.', 'A cidade é grande.']),
 'ja': ('発音とアクセント記号', "スペイン語は書いた通りに読みます。母音は a, e, i, o, u の五つで、はっきり発音します。\ne / i の前の c と z：スペインでは英語の「th」、中南米では「s」（cielo, zapato）。j と e / i の前の g：のどの奥の「ハ」のような音（jamón, gente）。a, o, u の前の g は「ガ行」、gue, gui の u は読みません。\nh は発音しません（hola）。ll と y は「ジャ・ヤ」に近い音。ñ は「ニャ」（año）。b と v は同じ音。\nr は舌を一回はじく音、rr と語頭の r は巻き舌（pero / perro）。\nアクセント：母音・n・s で終わる語は後ろから二番目の音節（casa, hablan）、それ以外は最後の音節（hablar, ciudad）。アクセント記号は例外を示し（café, árbol）、語を区別します（sí / si, él / el）。", ['犬がハムを食べます。', '町は大きいです。']),
 'zh': ('发音与重音符号', "西班牙语怎么写就怎么读。五个纯元音：a, e, i, o, u。\ne / i 前的 c 和 z：在西班牙读如英语的「th」，在拉丁美洲读作「s」（cielo, zapato）。j 以及 e / i 前的 g：喉音，类似汉语的「h」（jamón, gente）。a, o, u 前的 g 读硬音；gue, gui 中的 u 不发音。\nh 不发音（hola）。ll 和 y 读如「y」。ñ 读如「ny」（año）。b 和 v 发音相同。\n单个 r：舌尖弹一下；rr 和词首的 r：大舌颤音（pero / perro）。\n重音：以元音、n 或 s 结尾的词重音在倒数第二个音节（casa, hablan），否则在最后一个音节（hablar, ciudad）。重音符号标出例外（café, árbol）并区分词义（sí / si, él / el）。", ['狗在吃火腿。', '这座城市很大。']),
 'ko': ('발음과 강세 표시', "스페인어는 쓰인 대로 읽습니다. 모음은 a, e, i, o, u 다섯 개로 분명하게 발음합니다.\ne / i 앞의 c와 z: 스페인에서는 영어 「th」, 중남미에서는 「s」(cielo, zapato). j와 e / i 앞의 g: 목구멍에서 나는 「ㅎ」 소리(jamón, gente). a, o, u 앞의 g는 「ㄱ」, gue, gui의 u는 읽지 않습니다.\nh는 소리 나지 않습니다(hola). ll과 y는 「야」에 가까운 소리. ñ는 「냐」(año). b와 v는 같은 소리입니다.\nr은 혀를 한 번 튕기고, rr와 단어 처음의 r은 굴립니다(pero / perro).\n강세: 모음, n, s로 끝나면 끝에서 두 번째 음절(casa, hablan), 그 밖에는 마지막 음절(hablar, ciudad). 강세 표시는 예외를 나타내고(café, árbol) 단어를 구별합니다(sí / si, él / el).", ['개가 햄을 먹어요.', '도시가 커요.']),
 'lt': ('Tarimas ir kirčio ženklai', "Ispaniškai skaitoma taip, kaip rašoma. Penki gryni balsiai: a, e, i, o, u.\nc prieš e / i ir z: Ispanijoje kaip angliškas „th“, Lotynų Amerikoje kaip „s“ (cielo, zapato). j ir g prieš e / i: gerklinis garsas, kaip „ch“ (jamón, gente). g prieš a, o, u: kietas g; gue, gui u netariamas.\nh netariama (hola). ll ir y: kaip „j“. ñ: kaip „nj“ (año). b ir v tariami vienodai.\nVienas r: vienas liežuvio smūgis; rr ir žodžio pradžios r: virpamas (pero / perro).\nKirtis: priešpaskutiniame skiemenyje, jei žodis baigiasi balsiu, n ar s (casa, hablan); kitaip paskutiniame (hablar, ciudad). Kirčio ženklas žymi išimtis (café, árbol) ir skiria žodžius (sí / si, él / el).", ['Šuo ėda kumpį.', 'Miestas didelis.']),
 'tl': ('Pagbigkas at tuldik', "Binabasa ang Espanyol kung paano isinulat. Limang malinaw na patinig: a, e, i, o, u.\nc bago ang e / i at z: tulad ng «th» ng Ingles sa Espanya, «s» sa Latin America (cielo, zapato). j, at g bago ang e / i: tunog sa lalamunan, parang malakas na «h» (jamón, gente). g bago ang a, o, u: matigas na g; sa gue, gui hindi binibigkas ang u.\nWalang tunog ang h (hola). ll at y: parang «y». ñ: parang «ny» (año). Pareho ang tunog ng b at v.\nIsang r: isang pitik ng dila; rr at r sa simula: pinapagulong (pero / perro).\nDiin: sa ikalawa mula sa huli kung nagtatapos sa patinig, n o s (casa, hablan); kung hindi, sa huli (hablar, ciudad). Ang tuldik ay nagpapakita ng eksepsiyon (café, árbol) at nag-iiba ng salita (sí / si, él / el).", ['Kumakain ng hamon ang aso.', 'Malaki ang lungsod.']),
},
'genre': {
 'de': ('Genus und Artikel', "Nomen sind männlich oder weiblich. Meist ist -o männlich (el libro) und -a weiblich (la casa); häufige Ausnahmen: el día, el problema, la mano.\nBestimmte Artikel: el, la, los, las. Unbestimmte: un, una, unos, unas.\nPflicht-Zusammenziehungen: a + el = al, de + el = del.", ['Das Buch liegt auf dem Tisch.', 'Ich gehe auf den Markt.']),
 'it': ('Il genere e gli articoli', "I nomi sono maschili o femminili. In genere -o è maschile (el libro) e -a femminile (la casa); eccezioni frequenti: el día, el problema, la mano.\nArticoli determinativi: el, la, los, las. Indeterminativi: un, una, unos, unas.\nContrazioni obbligatorie: a + el = al, de + el = del.", ['Il libro è sul tavolo.', 'Vado al mercato.']),
 'pt': ('O gênero e os artigos', "Os substantivos são masculinos ou femininos. Em geral -o é masculino (el libro) e -a feminino (la casa); exceções frequentes: el día, el problema, la mano.\nArtigos definidos: el, la, los, las. Indefinidos: un, una, unos, unas.\nContrações obrigatórias: a + el = al, de + el = del.", ['O livro está na mesa.', 'Vou ao mercado.']),
 'ja': ('名詞の性と冠詞', "名詞は男性か女性です。ふつう -o は男性（el libro）、-a は女性（la casa）。よくある例外：el día, el problema, la mano。\n定冠詞：el, la, los, las。不定冠詞：un, una, unos, unas。\n必ず縮約します：a + el = al、de + el = del。", ['本はテーブルの上にあります。', '市場へ行きます。']),
 'zh': ('名词的性与冠词', "名词分阳性和阴性。一般 -o 为阳性（el libro），-a 为阴性（la casa）；常见例外：el día, el problema, la mano。\n定冠词：el, la, los, las。不定冠词：un, una, unos, unas。\n必须缩合：a + el = al，de + el = del。", ['书在桌子上。', '我去市场。']),
 'ko': ('명사의 성과 관사', "명사는 남성 아니면 여성입니다. 보통 -o는 남성(el libro), -a는 여성(la casa)이며, 흔한 예외로 el día, el problema, la mano가 있습니다.\n정관사: el, la, los, las. 부정관사: un, una, unos, unas.\n반드시 줄여 씁니다: a + el = al, de + el = del.", ['책은 탁자 위에 있어요.', '시장에 가요.']),
 'lt': ('Giminė ir artikeliai', "Daiktavardžiai yra vyriškosios arba moteriškosios giminės. Paprastai -o – vyriškoji (el libro), -a – moteriškoji (la casa); dažnos išimtys: el día, el problema, la mano.\nŽymimieji artikeliai: el, la, los, las. Nežymimieji: un, una, unos, unas.\nPrivalomi sutraukimai: a + el = al, de + el = del.", ['Knyga ant stalo.', 'Einu į turgų.']),
 'tl': ('Kasarian at mga pantukoy', "Panlalaki o pambabae ang mga pangngalan. Karaniwang panlalaki ang -o (el libro) at pambabae ang -a (la casa); madalas na eksepsiyon: el día, el problema, la mano.\nTiyak na pantukoy: el, la, los, las. Di-tiyak: un, una, unos, unas.\nSapilitang pagsasama: a + el = al, de + el = del.", ['Nasa mesa ang libro.', 'Pupunta ako sa palengke.']),
},
'pluriel': {
 'de': ('Plural und Angleichung des Adjektivs', "Plural: Vokal + s (casa → casas), Konsonant + es (ciudad → ciudades), -z → -ces (luz → luces).\nDas Adjektiv richtet sich nach Genus und Zahl und steht meist nach dem Nomen: un coche rojo, dos casas rojas. Adjektive auf -e oder Konsonant haben für beide Genera eine Form (grande, fácil).", ['Ich habe zwei schwarze Katzen.', 'Die Blumen sind hübsch.']),
 'it': ("Il plurale e l'accordo dell'aggettivo", "Plurale: vocale + s (casa → casas), consonante + es (ciudad → ciudades), -z → -ces (luz → luces).\nL'aggettivo si accorda in genere e numero e di solito segue il nome: un coche rojo, dos casas rojas. Gli aggettivi in -e o in consonante hanno una sola forma per i due generi (grande, fácil).", ['Ho due gatti neri.', 'I fiori sono belli.']),
 'pt': ('O plural e a concordância do adjetivo', "Plural: vogal + s (casa → casas), consoante + es (ciudad → ciudades), -z → -ces (luz → luces).\nO adjetivo concorda em gênero e número e costuma vir depois do substantivo: un coche rojo, dos casas rojas. Adjetivos em -e ou consoante têm a mesma forma nos dois gêneros (grande, fácil).", ['Tenho dois gatos pretos.', 'As flores são bonitas.']),
 'ja': ('複数形と形容詞の一致', "複数形：母音 + s（casa → casas）、子音 + es（ciudad → ciudades）、-z → -ces（luz → luces）。\n形容詞は性と数を名詞に合わせ、ふつう名詞の後に置きます：un coche rojo, dos casas rojas。-e や子音で終わる形容詞は男女同形です（grande, fácil）。", ['黒い猫を二匹飼っています。', '花がきれいです。']),
 'zh': ('复数与形容词的配合', "复数：元音 + s（casa → casas），辅音 + es（ciudad → ciudades），-z → -ces（luz → luces）。\n形容词与名词性数一致，通常放在名词后：un coche rojo, dos casas rojas。以 -e 或辅音结尾的形容词阴阳同形（grande, fácil）。", ['我有两只黑猫。', '花很漂亮。']),
 'ko': ('복수형과 형용사의 일치', "복수형: 모음 + s(casa → casas), 자음 + es(ciudad → ciudades), -z → -ces(luz → luces).\n형용사는 성과 수를 명사에 맞추고 보통 명사 뒤에 옵니다: un coche rojo, dos casas rojas. -e나 자음으로 끝나는 형용사는 남녀 같은 형태입니다(grande, fácil).", ['검은 고양이 두 마리가 있어요.', '꽃들이 예뻐요.']),
 'lt': ('Daugiskaita ir būdvardžio derinimas', "Daugiskaita: balsis + s (casa → casas), priebalsis + es (ciudad → ciudades), -z → -ces (luz → luces).\nBūdvardis derinamas gimine ir skaičiumi ir dažniausiai eina po daiktavardžio: un coche rojo, dos casas rojas. Būdvardžiai, besibaigiantys -e ar priebalsiu, abiem giminėms turi vieną formą (grande, fácil).", ['Turiu dvi juodas kates.', 'Gėlės gražios.']),
 'tl': ('Maramihan at pagtutugma ng pang-uri', "Maramihan: patinig + s (casa → casas), katinig + es (ciudad → ciudades), -z → -ces (luz → luces).\nTumutugma ang pang-uri sa kasarian at bilang at karaniwang sumusunod sa pangngalan: un coche rojo, dos casas rojas. Ang mga pang-uring nagtatapos sa -e o katinig ay iisa ang anyo (grande, fácil).", ['May dalawa akong itim na pusa.', 'Magaganda ang mga bulaklak.']),
},
'ser-estar': {
 'de': ('Ser und estar', "Zwei Verben für „sein“.\n„Ser“: Identität, Herkunft, Beruf, dauerhafte Eigenschaften, Uhrzeit. Soy francés. Es médico. Son las tres.\n„Estar“: Ort, vorübergehender Zustand, Ergebnis. Estoy en casa. Está cansada. La puerta está abierta.\nDie Bedeutung ändert sich: ser aburrido = langweilig sein, estar aburrido = sich langweilen.", ['Ich bin Student.', 'Wo bist du?', 'Wir sind sehr zufrieden.']),
 'it': ('Ser e estar', "Due verbi per «essere».\n«Ser»: identità, origine, professione, caratteristiche durature, ora. Soy francés. Es médico. Son las tres.\n«Estar»: luogo, stato passeggero, risultato. Estoy en casa. Está cansada. La puerta está abierta.\nIl senso cambia: ser aburrido = essere noioso, estar aburrido = annoiarsi.", ['Sono studente.', 'Dove sei?', 'Siamo molto contenti.']),
 'pt': ('Ser e estar', "Dois verbos, como em português, mas com usos um pouco diferentes.\n«Ser»: identidade, origem, profissão, características duradouras, hora. Soy francés. Es médico. Son las tres.\n«Estar»: lugar (em espanhol, mesmo para cidades e edifícios), estado passageiro, resultado. Estoy en casa. Está cansada. La puerta está abierta.\nO sentido muda: ser aburrido = ser chato, estar aburrido = estar entediado.", ['Sou estudante.', 'Onde você está?', 'Estamos muito contentes.']),
 'ja': ('ser と estar', "「〜である」を表す動詞が二つあります。\nser：正体、出身、職業、変わらない性質、時刻。Soy francés. Es médico. Son las tres。\nestar：場所、一時的な状態、結果。Estoy en casa. Está cansada. La puerta está abierta。\n意味が変わる例：ser aburrido = 退屈な人だ、estar aburrido = 退屈している。", ['私は学生です。', 'どこにいるの？', '私たちはとても満足しています。']),
 'zh': ('ser 与 estar', "两个动词都表示「是／在」。\nser：身份、来源、职业、持久特征、时间。Soy francés. Es médico. Son las tres。\nestar：位置、暂时状态、结果。Estoy en casa. Está cansada. La puerta está abierta。\n意思会变：ser aburrido = 令人厌烦，estar aburrido = 感到无聊。", ['我是学生。', '你在哪儿？', '我们非常高兴。']),
 'ko': ('ser와 estar', "「~이다」를 뜻하는 동사가 둘입니다.\nser: 정체, 출신, 직업, 변하지 않는 성질, 시각. Soy francés. Es médico. Son las tres.\nestar: 위치, 일시적인 상태, 결과. Estoy en casa. Está cansada. La puerta está abierta.\n뜻이 달라지는 예: ser aburrido = 지루한 사람이다, estar aburrido = 지루해하다.", ['저는 학생이에요.', '어디 있어요?', '우리는 아주 만족해요.']),
 'lt': ('Ser ir estar', "Du veiksmažodžiai „būti“.\n„Ser“: tapatybė, kilmė, profesija, ilgalaikės savybės, laikas. Soy francés. Es médico. Son las tres.\n„Estar“: vieta, laikina būsena, rezultatas. Estoy en casa. Está cansada. La puerta está abierta.\nReikšmė keičiasi: ser aburrido = būti nuobodžiam, estar aburrido = nuobodžiauti.", ['Aš studentas.', 'Kur tu esi?', 'Mes labai patenkinti.']),
 'tl': ('Ser at estar', "Dalawang pandiwa para sa «maging / naroon».\n«Ser»: pagkakakilanlan, pinagmulan, trabaho, permanenteng katangian, oras. Soy francés. Es médico. Son las tres.\n«Estar»: lugar, pansamantalang kalagayan, resulta. Estoy en casa. Está cansada. La puerta está abierta.\nNagbabago ang kahulugan: ser aburrido = nakakabagot, estar aburrido = nababagot.", ['Estudyante ako.', 'Nasaan ka?', 'Masayang-masaya kami.']),
},
'present': {
 'de': ('Das Präsens der regelmäßigen Verben', "Drei Gruppen: -ar, -er, -ir.\nhablar: hablo, hablas, habla, hablamos, habláis, hablan.\ncomer: como, comes, come, comemos, coméis, comen.\nvivir: vivo, vives, vive, vivimos, vivís, viven.\nDas Subjektpronomen fällt meist weg: Die Endung genügt. Verneinung: „no“ vor dem Verb (No hablo ruso).", ['Ich spreche Spanisch.', 'Wir wohnen in Madrid.', 'Ich esse kein Fleisch.']),
 'it': ('Il presente dei verbi regolari', "Tre gruppi: -ar, -er, -ir.\nhablar: hablo, hablas, habla, hablamos, habláis, hablan.\ncomer: como, comes, come, comemos, coméis, comen.\nvivir: vivo, vives, vive, vivimos, vivís, viven.\nIl pronome soggetto si omette quasi sempre: basta la desinenza. Negazione: «no» prima del verbo (No hablo ruso).", ['Parlo spagnolo.', 'Viviamo a Madrid.', 'Non mangio carne.']),
 'pt': ('O presente dos verbos regulares', "Três grupos: -ar, -er, -ir.\nhablar: hablo, hablas, habla, hablamos, habláis, hablan.\ncomer: como, comes, come, comemos, coméis, comen.\nvivir: vivo, vives, vive, vivimos, vivís, viven.\nO pronome sujeito costuma ser omitido: a terminação basta. Negação: «no» antes do verbo (No hablo ruso).", ['Falo espanhol.', 'Moramos em Madri.', 'Não como carne.']),
 'ja': ('規則動詞の現在形', "-ar, -er, -ir の三種類があります。\nhablar：hablo, hablas, habla, hablamos, habláis, hablan。\ncomer：como, comes, come, comemos, coméis, comen。\nvivir：vivo, vives, vive, vivimos, vivís, viven。\n主語の代名詞はふつう省略します。語尾で人称がわかるからです。否定は動詞の前に「no」（No hablo ruso）。", ['スペイン語を話します。', '私たちはマドリードに住んでいます。', '肉は食べません。']),
 'zh': ('规则动词的现在时', "分为三类：-ar、-er、-ir。\nhablar：hablo, hablas, habla, hablamos, habláis, hablan。\ncomer：como, comes, come, comemos, coméis, comen。\nvivir：vivo, vives, vive, vivimos, vivís, viven。\n主语代词通常省略，词尾已表明人称。否定：在动词前加「no」（No hablo ruso）。", ['我说西班牙语。', '我们住在马德里。', '我不吃肉。']),
 'ko': ('규칙 동사의 현재형', "세 가지가 있습니다: -ar, -er, -ir.\nhablar: hablo, hablas, habla, hablamos, habláis, hablan.\ncomer: como, comes, come, comemos, coméis, comen.\nvivir: vivo, vives, vive, vivimos, vivís, viven.\n주어 대명사는 보통 생략합니다. 어미로 인칭을 알 수 있기 때문입니다. 부정: 동사 앞에 「no」(No hablo ruso).", ['저는 스페인어를 해요.', '우리는 마드리드에 살아요.', '저는 고기를 안 먹어요.']),
 'lt': ('Taisyklingųjų veiksmažodžių esamasis laikas', "Trys grupės: -ar, -er, -ir.\nhablar: hablo, hablas, habla, hablamos, habláis, hablan.\ncomer: como, comes, come, comemos, coméis, comen.\nvivir: vivo, vives, vive, vivimos, vivís, viven.\nAsmeninis įvardis dažniausiai praleidžiamas – užtenka galūnės. Neiginys: „no“ prieš veiksmažodį (No hablo ruso).", ['Kalbu ispaniškai.', 'Gyvename Madride.', 'Nevalgau mėsos.']),
 'tl': ('Kasalukuyan ng mga regular na pandiwa', "Tatlong grupo: -ar, -er, -ir.\nhablar: hablo, hablas, habla, hablamos, habláis, hablan.\ncomer: como, comes, come, comemos, coméis, comen.\nvivir: vivo, vives, vive, vivimos, vivís, viven.\nKaraniwang hindi na sinasabi ang panghalip: sapat na ang hulapi. Negatibo: «no» bago ang pandiwa (No hablo ruso).", ['Nagsasalita ako ng Espanyol.', 'Nakatira kami sa Madrid.', 'Hindi ako kumakain ng karne.']),
},
'irreguliers': {
 'de': ('Präsens: unregelmäßige Verben und Stammwechsel', "Sehr häufig: ir (voy, vas, va, vamos, vais, van), tener (tengo, tienes, tiene, tenemos, tenéis, tienen), hacer (hago), decir (digo, dices), venir (vengo, vienes), poder (puedo), querer (quiero), saber (sé), dar (doy).\nStammwechsel unter Betonung: e → ie (pensar → pienso), o → ue (dormir → duermo), e → i (pedir → pido). Nosotros und vosotros behalten den einfachen Vokal: pensamos, dormimos.", ['Ich habe Hunger.', 'Kannst du mir helfen?', 'Ich gehe nach Hause.']),
 'it': ('Presente: verbi irregolari e dittonganti', "Molto frequenti: ir (voy, vas, va, vamos, vais, van), tener (tengo, tienes, tiene, tenemos, tenéis, tienen), hacer (hago), decir (digo, dices), venir (vengo, vienes), poder (puedo), querer (quiero), saber (sé), dar (doy).\nDittongo sotto l'accento: e → ie (pensar → pienso), o → ue (dormir → duermo), e → i (pedir → pido). Nosotros e vosotros mantengono la vocale semplice: pensamos, dormimos.", ['Ho fame.', 'Puoi aiutarmi?', 'Vado a casa.']),
 'pt': ('Presente: verbos irregulares e com ditongo', "Muito frequentes: ir (voy, vas, va, vamos, vais, van), tener (tengo, tienes, tiene, tenemos, tenéis, tienen), hacer (hago), decir (digo, dices), venir (vengo, vienes), poder (puedo), querer (quiero), saber (sé), dar (doy).\nDitongo na sílaba tônica: e → ie (pensar → pienso), o → ue (dormir → duermo), e → i (pedir → pido). Nosotros e vosotros mantêm a vogal simples: pensamos, dormimos.", ['Estou com fome.', 'Você pode me ajudar?', 'Vou para casa.']),
 'ja': ('現在形：不規則動詞と語幹母音変化', "よく使う不規則動詞：ir（voy, vas, va, vamos, vais, van）、tener（tengo, tienes, tiene, tenemos, tenéis, tienen）、hacer（hago）、decir（digo, dices）、venir（vengo, vienes）、poder（puedo）、querer（quiero）、saber（sé）、dar（doy）。\nアクセントのある語幹の母音が変わる動詞：e → ie（pensar → pienso）、o → ue（dormir → duermo）、e → i（pedir → pido）。nosotros と vosotros は変わりません：pensamos, dormimos。", ['お腹がすいています。', '手伝ってくれる？', '家に帰ります。']),
 'zh': ('现在时：不规则动词与词根变化', "非常常用：ir（voy, vas, va, vamos, vais, van），tener（tengo, tienes, tiene, tenemos, tenéis, tienen），hacer（hago），decir（digo, dices），venir（vengo, vienes），poder（puedo），querer（quiero），saber（sé），dar（doy）。\n重读时词根元音变化：e → ie（pensar → pienso），o → ue（dormir → duermo），e → i（pedir → pido）。nosotros 和 vosotros 保持原元音：pensamos, dormimos。", ['我饿了。', '你能帮我吗？', '我回家。']),
 'ko': ('현재형: 불규칙 동사와 어간 모음 변화', "아주 자주 쓰는 동사: ir(voy, vas, va, vamos, vais, van), tener(tengo, tienes, tiene, tenemos, tenéis, tienen), hacer(hago), decir(digo, dices), venir(vengo, vienes), poder(puedo), querer(quiero), saber(sé), dar(doy).\n강세가 오는 어간 모음이 바뀌는 동사: e → ie(pensar → pienso), o → ue(dormir → duermo), e → i(pedir → pido). nosotros와 vosotros는 바뀌지 않습니다: pensamos, dormimos.", ['배고파요.', '도와줄 수 있어요?', '집에 가요.']),
 'lt': ('Esamasis laikas: netaisyklingi ir kamieną keičiantys veiksmažodžiai', "Labai dažni: ir (voy, vas, va, vamos, vais, van), tener (tengo, tienes, tiene, tenemos, tenéis, tienen), hacer (hago), decir (digo, dices), venir (vengo, vienes), poder (puedo), querer (quiero), saber (sé), dar (doy).\nKirčiuotas kamieno balsis kinta: e → ie (pensar → pienso), o → ue (dormir → duermo), e → i (pedir → pido). Nosotros ir vosotros išlaiko paprastą balsį: pensamos, dormimos.", ['Esu alkanas.', 'Ar gali man padėti?', 'Einu namo.']),
 'tl': ('Kasalukuyan: di-regular na pandiwa', "Napakadalas: ir (voy, vas, va, vamos, vais, van), tener (tengo, tienes, tiene, tenemos, tenéis, tienen), hacer (hago), decir (digo, dices), venir (vengo, vienes), poder (puedo), querer (quiero), saber (sé), dar (doy).\nNagbabago ang patinig ng ugat kapag may diin: e → ie (pensar → pienso), o → ue (dormir → duermo), e → i (pedir → pido). Hindi nagbabago sa nosotros at vosotros: pensamos, dormimos.", ['Gutom ako.', 'Matutulungan mo ba ako?', 'Uuwi na ako.']),
},
'questions': {
 'de': ('Fragen und Verneinung', "Fragen stehen zwischen ¿ und ?; die Wortstellung ändert sich kaum, die Intonation macht die Frage: ¿Hablas inglés?\nFragewörter tragen immer einen Akzent: qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\nVerneinungen: no, nunca (nie), nada (nichts), nadie (niemand). Doppelte Verneinung ist normal: No veo nada.", ['Wo wohnst du?', 'Ich habe nichts.']),
 'it': ('Domande e negazione', "La domanda si scrive tra ¿ e ?; l'ordine delle parole cambia poco, conta l'intonazione: ¿Hablas inglés?\nParole interrogative, sempre accentate: qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\nNegazioni: no, nunca (mai), nada (niente), nadie (nessuno). La doppia negazione è normale: No veo nada.", ['Dove abiti?', 'Non ho niente.']),
 'pt': ('Perguntas e negação', "A pergunta escreve-se entre ¿ e ?; a ordem das palavras quase não muda, é a entonação que conta: ¿Hablas inglés?\nPalavras interrogativas, sempre acentuadas: qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\nNegações: no, nunca, nada, nadie (ninguém). Dupla negação é normal: No veo nada.", ['Onde você mora?', 'Não tenho nada.']),
 'ja': ('疑問文と否定', "疑問文は ¿ と ? ではさみます。語順はほとんど変わらず、イントネーションで尋ねます：¿Hablas inglés?\n疑問詞にはいつもアクセント記号がつきます：qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál。\n否定語：no, nunca（決して）、nada（何も）、nadie（誰も）。二重否定がふつうです：No veo nada。", ['どこに住んでいるの？', '何も持っていません。']),
 'zh': ('疑问与否定', "疑问句写在 ¿ 和 ? 之间；语序基本不变，靠语调提问：¿Hablas inglés?\n疑问词总带重音符号：qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál。\n否定词：no, nunca（从不），nada（什么也不），nadie（没有人）。双重否定很正常：No veo nada。", ['你住在哪儿？', '我什么也没有。']),
 'ko': ('의문문과 부정', "의문문은 ¿와 ? 사이에 씁니다. 어순은 거의 바뀌지 않고 억양으로 묻습니다: ¿Hablas inglés?\n의문사에는 항상 강세 표시가 붙습니다: qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\n부정어: no, nunca(결코), nada(아무것도), nadie(아무도). 이중 부정이 자연스럽습니다: No veo nada.", ['어디 살아요?', '아무것도 없어요.']),
 'lt': ('Klausimai ir neiginys', "Klausimas rašomas tarp ¿ ir ?; žodžių tvarka beveik nesikeičia, svarbi intonacija: ¿Hablas inglés?\nKlausiamieji žodžiai visada su kirčio ženklu: qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\nNeiginiai: no, nunca (niekada), nada (nieko), nadie (niekas). Dvigubas neiginys įprastas: No veo nada.", ['Kur tu gyveni?', 'Nieko neturiu.']),
 'tl': ('Tanong at negatibo', "Isinusulat ang tanong sa pagitan ng ¿ at ?; halos hindi nagbabago ang ayos, ang intonasyon ang mahalaga: ¿Hablas inglés?\nLaging may tuldik ang mga salitang pananong: qué, quién, dónde, cuándo, cómo, cuánto, por qué, cuál.\nMga negatibo: no, nunca (hindi kailanman), nada (wala), nadie (walang sinuman). Karaniwan ang dobleng negatibo: No veo nada.", ['Saan ka nakatira?', 'Wala akong kahit ano.']),
},
'gustar': {
 'de': ('Gustar: mögen', "„Gustar“ funktioniert wie „gefallen“: Me gusta el café (Kaffee gefällt mir). Das Verb richtet sich nach dem, was man mag: Me gustan los gatos.\nPronomen: me, te, le, nos, os, les. Zur Verdeutlichung oder Betonung: A mí me gusta, a Juan le gusta.\nGleiche Konstruktion: encantar, doler, interesar, parecer.", ['Ich mag Musik.', 'Magst du Hunde?']),
 'it': ('Gustar: piacere', "«Gustar» funziona proprio come «piacere»: Me gusta el café (mi piace il caffè). Il verbo concorda con ciò che piace: Me gustan los gatos.\nPronomi: me, te, le, nos, os, les. Per precisare o insistere: A mí me gusta, a Juan le gusta.\nStessa costruzione: encantar, doler, interesar, parecer.", ['Mi piace la musica.', 'Ti piacciono i cani?']),
 'pt': ('Gustar: gostar', "«Gustar» funciona como «agradar»: Me gusta el café (o café me agrada = gosto de café). O verbo concorda com a coisa de que se gosta: Me gustan los gatos.\nPronomes: me, te, le, nos, os, les. Para precisar ou insistir: A mí me gusta, a Juan le gusta.\nMesma construção: encantar, doler, interesar, parecer.", ['Gosto de música.', 'Você gosta de cachorros?']),
 'ja': ('gustar：好き', "gustar は「〜が気に入る」という形です：Me gusta el café（コーヒーが私に気に入る＝コーヒーが好き）。動詞は好きなものに合わせます：Me gustan los gatos。\n代名詞：me, te, le, nos, os, les。はっきりさせたり強調したりするとき：A mí me gusta、a Juan le gusta。\n同じ形の動詞：encantar, doler, interesar, parecer。", ['音楽が好きです。', '犬は好き？']),
 'zh': ('gustar：喜欢', "gustar 的结构是「……让某人喜欢」：Me gusta el café（咖啡让我喜欢 = 我喜欢咖啡）。动词随所喜欢的事物变化：Me gustan los gatos。\n代词：me, te, le, nos, os, les。需要明确或强调时：A mí me gusta，a Juan le gusta。\n同样结构：encantar, doler, interesar, parecer。", ['我喜欢音乐。', '你喜欢狗吗？']),
 'ko': ('gustar: 좋아하다', "gustar는 「~가 마음에 들다」 구조입니다: Me gusta el café(커피가 나에게 마음에 든다 = 커피를 좋아한다). 동사는 좋아하는 대상에 맞춥니다: Me gustan los gatos.\n대명사: me, te, le, nos, os, les. 분명히 하거나 강조할 때: A mí me gusta, a Juan le gusta.\n같은 구조: encantar, doler, interesar, parecer.", ['음악을 좋아해요.', '개 좋아해요?']),
 'lt': ('Gustar: patikti', "„Gustar“ veikia kaip „patikti“: Me gusta el café (man patinka kava). Veiksmažodis derinamas su tuo, kas patinka: Me gustan los gatos.\nĮvardžiai: me, te, le, nos, os, les. Patikslinti ar pabrėžti: A mí me gusta, a Juan le gusta.\nTokia pati konstrukcija: encantar, doler, interesar, parecer.", ['Man patinka muzika.', 'Ar tau patinka šunys?']),
 'tl': ('Gustar: magustuhan', "Ang «gustar» ay parang «magustuhan ng»: Me gusta el café (gusto ko ang kape). Tumutugma ang pandiwa sa bagay na gusto: Me gustan los gatos.\nMga panghalip: me, te, le, nos, os, les. Para linawin o idiin: A mí me gusta, a Juan le gusta.\nGanito rin: encantar, doler, interesar, parecer.", ['Gusto ko ang musika.', 'Gusto mo ba ang mga aso?']),
},
'possessifs-demonstratifs': {
 'de': ('Possessiv- und Demonstrativbegleiter', "Possessiv: mi, tu, su, nuestro/a, vuestro/a, su (Plural: mis, tus, sus…). „Su“ steht für sein, ihr, Ihr.\nDemonstrativ, drei Entfernungen: este / esta (hier), ese / esa (da), aquel / aquella (dort drüben). Neutrum für eine Idee: esto, eso, aquello.", ['Das ist mein Bruder.', 'Was ist das?']),
 'it': ('Possessivi e dimostrativi', "Possessivi: mi, tu, su, nuestro/a, vuestro/a, su (plurale: mis, tus, sus…), senza articolo. «Su» vale per suo, sua, loro, Suo.\nDimostrativi, tre gradi di distanza: este / esta (qui), ese / esa (lì), aquel / aquella (là). Neutri per un'idea: esto, eso, aquello.", ['Questo è mio fratello.', "Che cos'è quello?"]),
 'pt': ('Possessivos e demonstrativos', "Possessivos: mi, tu, su, nuestro/a, vuestro/a, su (plural: mis, tus, sus…), sem artigo. «Su» vale para seu, sua, dele, dela, deles.\nDemonstrativos, três graus de distância: este / esta (aqui), ese / esa (aí), aquel / aquella (lá). Neutros para uma ideia: esto, eso, aquello.", ['Este é meu irmão.', 'O que é isso?']),
 'ja': ('所有詞と指示詞', "所有詞：mi, tu, su, nuestro/a, vuestro/a, su（複数：mis, tus, sus…）。su は「彼の・彼女の・あなたの・彼らの」。\n指示詞は距離が三段階：este / esta（これ、話し手の近く）、ese / esa（それ）、aquel / aquella（あれ）。考えや事がらには中性形 esto, eso, aquello。", ['こちらは私の兄です。', 'それは何？']),
 'zh': ('物主形容词与指示词', "物主形容词：mi, tu, su, nuestro/a, vuestro/a, su（复数：mis, tus, sus…）。su 可指他的、她的、您的、他们的。\n指示词分三种距离：este / esta（这，近处），ese / esa（那，较近），aquel / aquella（那，远处）。指一件事用中性：esto, eso, aquello。", ['这是我哥哥。', '那是什么？']),
 'ko': ('소유사와 지시사', "소유사: mi, tu, su, nuestro/a, vuestro/a, su(복수: mis, tus, sus…). su는 그의, 그녀의, 당신의, 그들의를 모두 나타냅니다.\n지시사는 거리에 따라 셋: este / esta(이, 가까이), ese / esa(그), aquel / aquella(저, 멀리). 생각이나 일에는 중성 esto, eso, aquello.", ['이쪽은 제 형이에요.', '그게 뭐예요?']),
 'lt': ('Savybiniai ir parodomieji žodžiai', "Savybiniai: mi, tu, su, nuestro/a, vuestro/a, su (daugiskaita: mis, tus, sus…). „Su“ reiškia jo, jos, jūsų, jų.\nParodomieji, trys atstumai: este / esta (šis, čia), ese / esa (tas, ten), aquel / aquella (anas, toli). Bevardės giminės idėjai: esto, eso, aquello.", ['Tai mano brolis.', 'Kas tai?']),
 'tl': ('Paari at pamatlig', "Paari: mi, tu, su, nuestro/a, vuestro/a, su (maramihan: mis, tus, sus…). Ang «su» ay kaniya, ninyo (magalang), nila.\nPamatlig, tatlong layo: este / esta (ito), ese / esa (iyan), aquel / aquella (iyon). Para sa ideya: esto, eso, aquello.", ['Ito ang kapatid kong lalaki.', 'Ano iyan?']),
},
'ir-a': {
 'de': ('Nahe Zukunft und Gerundium', "Nahe Zukunft: ir a + Infinitiv. Voy a comer = ich werde gleich essen.\nLaufende Handlung: estar + Gerundium (-ando bei -ar, -iendo bei -er / -ir). Estoy trabajando. Está lloviendo.\nGerade Geschehenes: acabar de + Infinitiv. Acabo de llegar = ich bin gerade angekommen.", ['Wir gehen heute Abend aus.', 'Was machst du gerade?']),
 'it': ('Il futuro prossimo e il gerundio', "Futuro prossimo: ir a + infinito. Voy a comer = sto per mangiare.\nAzione in corso: estar + gerundio (-ando per -ar, -iendo per -er / -ir). Estoy trabajando. Está lloviendo.\nPassato recente: acabar de + infinito. Acabo de llegar = sono appena arrivato.", ['Stasera usciamo.', 'Che cosa stai facendo?']),
 'pt': ('O futuro próximo e o gerúndio', "Futuro próximo: ir a + infinitivo (com «a», ao contrário do português). Voy a comer = vou comer.\nAção em curso: estar + gerúndio (-ando para -ar, -iendo para -er / -ir). Estoy trabajando. Está lloviendo.\nPassado recente: acabar de + infinitivo. Acabo de llegar = acabei de chegar.", ['Vamos sair hoje à noite.', 'O que você está fazendo?']),
 'ja': ('近い未来と現在分詞', "近い未来：ir a + 不定詞。Voy a comer = これから食べます。\n進行中の動作：estar + 現在分詞（-ar 動詞は -ando、-er / -ir 動詞は -iendo）。Estoy trabajando. Está lloviendo。\n直前の過去：acabar de + 不定詞。Acabo de llegar = 着いたばかりです。", ['今夜出かけます。', '何をしているの？']),
 'zh': ('近将来时与副动词', "近将来时：ir a + 不定式。Voy a comer = 我要吃饭了。\n正在进行：estar + 副动词（-ar 动词用 -ando，-er / -ir 动词用 -iendo）。Estoy trabajando. Está lloviendo。\n刚刚完成：acabar de + 不定式。Acabo de llegar = 我刚到。", ['我们今晚要出去。', '你在做什么？']),
 'ko': ('가까운 미래와 현재분사', "가까운 미래: ir a + 동사원형. Voy a comer = 곧 먹을 거예요.\n진행 중인 동작: estar + 현재분사(-ar 동사는 -ando, -er / -ir 동사는 -iendo). Estoy trabajando. Está lloviendo.\n방금 한 일: acabar de + 동사원형. Acabo de llegar = 방금 도착했어요.", ['오늘 밤에 나갈 거예요.', '뭐 하고 있어요?']),
 'lt': ('Artimasis būsimasis ir padalyvis', "Artimasis būsimasis: ir a + bendratis. Voy a comer = tuoj valgysiu.\nVykstantis veiksmas: estar + padalyvis (-ando veiksmažodžiams -ar, -iendo – -er / -ir). Estoy trabajando. Está lloviendo.\nKą tik įvykęs veiksmas: acabar de + bendratis. Acabo de llegar = ką tik atvykau.", ['Šįvakar eisime į miestą.', 'Ką tu darai?']),
 'tl': ('Malapit na hinaharap at gerundio', "Malapit na hinaharap: ir a + infinitive. Voy a comer = kakain ako.\nKilos na nangyayari: estar + gerundio (-ando sa -ar, -iendo sa -er / -ir). Estoy trabajando. Está lloviendo.\nKatatapos lang: acabar de + infinitive. Acabo de llegar = kararating ko lang.", ['Lalabas kami mamayang gabi.', 'Ano ang ginagawa mo?']),
},
'preterito': {
 'de': ('Das Indefinido (Präteritum)', "Abgeschlossene Handlung zu einem bestimmten Zeitpunkt der Vergangenheit. Die normale Erzählzeit, auch mündlich.\n-ar: hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir: comí, comiste, comió, comimos, comisteis, comieron.\nHäufige unregelmäßige: ser / ir (fui, fuiste, fue, fuimos, fueron), tener (tuve), estar (estuve), hacer (hice, hizo), decir (dije), poder (pude), venir (vine).", ['Gestern habe ich Paella gegessen.', 'Wir sind ins Kino gegangen.']),
 'it': ('Il passato remoto (pretérito indefinido)', "Azione conclusa in un momento preciso del passato. È il tempo normale del racconto, anche nel parlato (dove l'italiano userebbe spesso il passato prossimo).\n-ar: hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir: comí, comiste, comió, comimos, comisteis, comieron.\nIrregolari frequenti: ser / ir (fui, fuiste, fue, fuimos, fueron), tener (tuve), estar (estuve), hacer (hice, hizo), decir (dije), poder (pude), venir (vine).", ['Ieri ho mangiato la paella.', 'Siamo andati al cinema.']),
 'pt': ('O pretérito perfeito (indefinido)', "Ação concluída num momento preciso do passado, como o pretérito perfeito português.\n-ar: hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir: comí, comiste, comió, comimos, comisteis, comieron.\nIrregulares frequentes: ser / ir (fui, fuiste, fue, fuimos, fueron), tener (tuve), estar (estuve), hacer (hice, hizo), decir (dije), poder (pude), venir (vine).", ['Ontem comi paella.', 'Fomos ao cinema.']),
 'ja': ('点過去', "過去のある時点で完了した動作。話し言葉でもふつうに使う物語の時制です。\n-ar 動詞：hablé, hablaste, habló, hablamos, hablasteis, hablaron。\n-er / -ir 動詞：comí, comiste, comió, comimos, comisteis, comieron。\nよく使う不規則形：ser / ir（fui, fuiste, fue, fuimos, fueron）、tener（tuve）、estar（estuve）、hacer（hice, hizo）、decir（dije）、poder（pude）、venir（vine）。", ['昨日パエリアを食べました。', '映画に行きました。']),
 'zh': ('简单过去时', "表示在过去某一时刻已完成的动作，是口语和叙述中常用的时态。\n-ar：hablé, hablaste, habló, hablamos, hablasteis, hablaron。\n-er / -ir：comí, comiste, comió, comimos, comisteis, comieron。\n常见不规则：ser / ir（fui, fuiste, fue, fuimos, fueron），tener（tuve），estar（estuve），hacer（hice, hizo），decir（dije），poder（pude），venir（vine）。", ['昨天我吃了海鲜饭。', '我们去看电影了。']),
 'ko': ('단순 과거', "과거의 특정 시점에 끝난 동작. 말할 때도 흔히 쓰는 이야기의 시제입니다.\n-ar: hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir: comí, comiste, comió, comimos, comisteis, comieron.\n자주 쓰는 불규칙형: ser / ir(fui, fuiste, fue, fuimos, fueron), tener(tuve), estar(estuve), hacer(hice, hizo), decir(dije), poder(pude), venir(vine).", ['어제 파에야를 먹었어요.', '우리는 영화관에 갔어요.']),
 'lt': ('Būtasis kartinis laikas (pretérito indefinido)', "Konkrečiu praeities momentu pasibaigęs veiksmas. Įprastas pasakojimo laikas, ir šnekamojoje kalboje.\n-ar: hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir: comí, comiste, comió, comimos, comisteis, comieron.\nDažni netaisyklingi: ser / ir (fui, fuiste, fue, fuimos, fueron), tener (tuve), estar (estuve), hacer (hice, hizo), decir (dije), poder (pude), venir (vine).", ['Vakar valgiau paeliją.', 'Nuėjome į kiną.']),
 'tl': ('Ang pretérito (nakaraan)', "Kilos na natapos sa tiyak na sandali sa nakaraan. Karaniwang panahunan ng pagkukuwento, pati sa usapan.\n-ar: hablé, hablaste, habló, hablamos, hablasteis, hablaron.\n-er / -ir: comí, comiste, comió, comimos, comisteis, comieron.\nMadalas na di-regular: ser / ir (fui, fuiste, fue, fuimos, fueron), tener (tuve), estar (estuve), hacer (hice, hizo), decir (dije), poder (pude), venir (vine).", ['Kumain ako ng paella kahapon.', 'Nanood kami ng sine.']),
},
'imperfecto': {
 'de': ('Das Imperfekt im Vergleich zum Indefinido', "-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir: comía, comías, comía, comíamos, comíais, comían. Nur drei unregelmäßige: ser (era), ir (iba), ver (veía).\nDas Imperfekt beschreibt Hintergrund, Gewohnheit, laufende Handlung; das Indefinido das eintretende Ereignis: Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono.", ['Als ich jung war, spielte ich Fußball.', 'Es war kalt.']),
 'it': ("L'imperfetto e il suo uso rispetto al passato remoto", "-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir: comía, comías, comía, comíamos, comíais, comían. Solo tre irregolari: ser (era), ir (iba), ver (veía).\nL'imperfetto descrive lo sfondo, l'abitudine, l'azione in corso; il passato remoto l'evento che accade: Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono.", ['Da giovane giocavo a calcio.', 'Faceva freddo.']),
 'pt': ('O imperfeito e o seu uso face ao perfeito', "-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir: comía, comías, comía, comíamos, comíais, comían. Só três irregulares: ser (era), ir (iba), ver (veía).\nO imperfeito descreve o cenário, o hábito, a ação em curso; o perfeito, o acontecimento: Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono.", ['Quando eu era jovem, jogava futebol.', 'Fazia frio.']),
 'ja': ('線過去と点過去の使い分け', "-ar 動詞：hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban。-er / -ir 動詞：comía, comías, comía, comíamos, comíais, comían。不規則は三つだけ：ser（era）、ir（iba）、ver（veía）。\n線過去は背景・習慣・進行中の動作、点過去は起こった出来事を表します：Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono。", ['若いころサッカーをしていました。', '寒かったです。']),
 'zh': ('过去未完成时及其与简单过去时的区别', "-ar：hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban。-er / -ir：comía, comías, comía, comíamos, comíais, comían。只有三个不规则：ser（era），ir（iba），ver（veía）。\n未完成时描述背景、习惯和正在进行的动作；简单过去时表示发生的事件：Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono。", ['我年轻时踢足球。', '那时很冷。']),
 'ko': ('불완료 과거와 단순 과거의 구별', "-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir: comía, comías, comía, comíamos, comíais, comían. 불규칙은 셋뿐입니다: ser(era), ir(iba), ver(veía).\n불완료 과거는 배경, 습관, 진행 중인 동작을, 단순 과거는 일어난 사건을 나타냅니다: Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono.", ['젊었을 때 축구를 했어요.', '추웠어요.']),
 'lt': ('Būtasis dažninis (imperfecto) ir jo skirtumas', "-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir: comía, comías, comía, comíamos, comíais, comían. Tik trys netaisyklingi: ser (era), ir (iba), ver (veía).\nImperfecto aprašo foną, įprotį, vykstantį veiksmą; indefinido – įvykusį įvykį: Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono.", ['Kai buvau jaunas, žaidžiau futbolą.', 'Buvo šalta.']),
 'tl': ('Ang imperfecto at ang pagkakaiba nito', "-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban. -er / -ir: comía, comías, comía, comíamos, comíais, comían. Tatlo lang ang di-regular: ser (era), ir (iba), ver (veía).\nInilalarawan ng imperfecto ang tagpo, gawi at kilos na nangyayari; ang pretérito ang pangyayaring naganap: Cuando era niño, vivía en Lima. Leía cuando sonó el teléfono.", ['Noong bata ako, naglalaro ako ng futbol.', 'Malamig noon.']),
},
'pronoms-objet': {
 'de': ('Objektpronomen', "Direkt: me, te, lo / la, nos, os, los / las. Indirekt: me, te, le, nos, os, les.\nSie stehen vor dem konjugierten Verb (Lo veo) oder werden an Infinitiv, Gerundium und bejahten Imperativ angehängt (Quiero verlo. Dímelo).\nIndirekt + direkt: das indirekte zuerst, und le / les wird vor lo / la zu „se“: Se lo doy.", ['Ich weiß es nicht.', 'Ich sage es dir morgen.']),
 'it': ('I pronomi complemento', "Diretti: me, te, lo / la, nos, os, los / las. Indiretti: me, te, le, nos, os, les.\nSi mettono prima del verbo coniugato (Lo veo) o si attaccano a infinito, gerundio e imperativo affermativo (Quiero verlo. Dímelo).\nIndiretto + diretto: prima l'indiretto, e le / les diventa «se» davanti a lo / la: Se lo doy.", ['Non lo so.', 'Te lo dico domani.']),
 'pt': ('Os pronomes complemento', "Diretos: me, te, lo / la, nos, os, los / las. Indiretos: me, te, le, nos, os, les.\nVêm antes do verbo conjugado (Lo veo) ou ligam-se ao infinitivo, ao gerúndio e ao imperativo afirmativo, sem hífen (Quiero verlo. Dímelo).\nIndireto + direto: primeiro o indireto, e le / les vira «se» antes de lo / la: Se lo doy.", ['Não sei.', 'Te digo amanhã.']),
 'ja': ('目的格代名詞', "直接目的語：me, te, lo / la, nos, os, los / las。間接目的語：me, te, le, nos, os, les。\n活用した動詞の前に置くか（Lo veo）、不定詞・現在分詞・肯定命令の後ろにつけます（Quiero verlo. Dímelo）。\n間接 + 直接の順。lo / la の前では le / les が se になります：Se lo doy。", ['知りません。', '明日あなたに言います。']),
 'zh': ('宾格代词', "直接宾语：me, te, lo / la, nos, os, los / las。间接宾语：me, te, le, nos, os, les。\n放在变位动词前（Lo veo），或连写在不定式、副动词和肯定命令式后（Quiero verlo. Dímelo）。\n间接 + 直接：间接在前；在 lo / la 前 le / les 变成 se：Se lo doy。", ['我不知道。', '我明天告诉你。']),
 'ko': ('목적격 대명사', "직접 목적어: me, te, lo / la, nos, os, los / las. 간접 목적어: me, te, le, nos, os, les.\n활용된 동사 앞에 두거나(Lo veo), 동사원형, 현재분사, 긍정 명령 뒤에 붙입니다(Quiero verlo. Dímelo).\n간접 + 직접 순서이며, lo / la 앞에서 le / les는 se가 됩니다: Se lo doy.", ['몰라요.', '내일 말해 줄게요.']),
 'lt': ('Papildinio įvardžiai', "Tiesioginiai: me, te, lo / la, nos, os, los / las. Netiesioginiai: me, te, le, nos, os, les.\nJie eina prieš asmenuojamą veiksmažodį (Lo veo) arba prijungiami prie bendraties, padalyvio ir teigiamos liepiamosios nuosakos (Quiero verlo. Dímelo).\nNetiesioginis + tiesioginis: pirmas netiesioginis, o le / les prieš lo / la virsta „se“: Se lo doy.", ['Nežinau.', 'Pasakysiu tau rytoj.']),
 'tl': ('Mga panghalip na layon', "Tuwiran: me, te, lo / la, nos, os, los / las. Di-tuwiran: me, te, le, nos, os, les.\nInilalagay bago ang binanghay na pandiwa (Lo veo) o idinidikit sa infinitive, gerundio at utos na apirmatibo (Quiero verlo. Dímelo).\nDi-tuwiran + tuwiran: nauuna ang di-tuwiran, at nagiging «se» ang le / les bago ang lo / la: Se lo doy.", ['Hindi ko alam.', 'Sasabihin ko sa iyo bukas.']),
},
'por-para': {
 'de': ('Por und para', "„Para“: Zweck, Empfänger, Ziel, Frist. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\n„Por“: Grund, Mittel, Dauer, Tausch, Weg durch einen Ort, Urheber im Passiv. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro.", ['Dieses Geschenk ist für dich.', 'Danke für deine Hilfe.']),
 'it': ('Por e para', "«Para»: scopo, destinatario, destinazione, scadenza. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\n«Por»: causa, mezzo, durata, scambio, luogo attraversato, agente del passivo. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro.", ['Questo regalo è per te.', 'Grazie per il tuo aiuto.']),
 'pt': ('Por e para', "«Para»: finalidade, destinatário, destino, prazo. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\n«Por»: causa, meio, duração, troca, lugar por onde se passa, agente da passiva. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro.", ['Este presente é para você.', 'Obrigado pela sua ajuda.']),
 'ja': ('por と para', "para：目的、受け取る人、行き先、期限。Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes。\npor：理由、手段、期間、交換、通過する場所、受動態の動作主。Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro。", ['このプレゼントはあなたにです。', '手伝ってくれてありがとう。']),
 'zh': ('por 与 para', "para：目的、对象、目的地、期限。Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes。\npor：原因、方式、时段、交换、经过的地方、被动句的施事者。Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro。", ['这个礼物是给你的。', '谢谢你的帮助。']),
 'ko': ('por와 para', "para: 목적, 받는 사람, 목적지, 기한. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\npor: 이유, 수단, 기간, 교환, 지나가는 장소, 수동태의 행위자. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro.", ['이 선물은 당신 거예요.', '도와줘서 고마워요.']),
 'lt': ('Por ir para', "„Para“: tikslas, gavėjas, kryptis, terminas. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\n„Por“: priežastis, priemonė, trukmė, mainai, vieta, per kurią einama, veikėjas neveikiamojoje rūšyje. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro.", ['Ši dovana tau.', 'Ačiū už pagalbą.']),
 'tl': ('Por at para', "«Para»: layunin, tatanggap, patutunguhan, takdang oras. Es para ti. Estudio para aprender. Salgo para Madrid. Para el lunes.\n«Por»: dahilan, paraan, tagal, palitan, dinaanang lugar, gumagawa sa balintiyak. Gracias por todo. Por teléfono. Por la mañana. Pagué diez euros por el libro.", ['Para sa iyo ang regalong ito.', 'Salamat sa tulong mo.']),
},
'perfecto': {
 'de': ('Das Perfekt (pretérito perfecto)', "haber im Präsens + Partizip: he, has, ha, hemos, habéis, han + hablado / comido / vivido. Das Partizip ist unveränderlich und wird nie von haber getrennt.\nUnregelmäßige Partizipien: hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\nIn Spanien für einen noch nicht abgeschlossenen Zeitraum (hoy, esta semana); in Lateinamerika steht oft das Indefinido.", ['Ich habe die Schlüssel verloren.', 'Warst du schon in Mexiko?']),
 'it': ('Il passato prossimo (pretérito perfecto)', "haber al presente + participio: he, has, ha, hemos, habéis, han + hablado / comido / vivido. Il participio è invariabile e non si separa da haber (sempre haber, mai ser).\nParticipi irregolari: hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\nIn Spagna si usa per un periodo non concluso (hoy, esta semana); in America Latina spesso lo sostituisce il passato remoto.", ['Ho perso le chiavi.', 'Sei mai stato in Messico?']),
 'pt': ('O pretérito perfeito composto (perfecto)', "haber no presente + particípio: he, has, ha, hemos, habéis, han + hablado / comido / vivido. O particípio é invariável e não se separa de haber.\nParticípios irregulares: hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\nAtenção: ao contrário do português «tenho falado», é um passado comum na Espanha para um período não terminado (hoy, esta semana); na América Latina usa-se mais o indefinido.", ['Perdi as chaves.', 'Você já esteve no México?']),
 'ja': ('現在完了', "haber の現在形 + 過去分詞：he, has, ha, hemos, habéis, han + hablado / comido / vivido。過去分詞は変化せず、haber と離れません。\n不規則な過去分詞：hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto。\nスペインでは終わっていない期間（hoy, esta semana）に使います。中南米では点過去がよく代わりに使われます。", ['鍵をなくしてしまいました。', 'メキシコに行ったことがありますか？']),
 'zh': ('现在完成时', "haber 的现在时 + 过去分词：he, has, ha, hemos, habéis, han + hablado / comido / vivido。过去分词不变化，也不与 haber 分开。\n不规则过去分词：hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto。\n在西班牙用于尚未结束的时间段（hoy, esta semana）；在拉丁美洲常用简单过去时代替。", ['我把钥匙弄丢了。', '你去过墨西哥吗？']),
 'ko': ('현재완료', "haber 현재형 + 과거분사: he, has, ha, hemos, habéis, han + hablado / comido / vivido. 과거분사는 변하지 않고 haber와 떨어지지 않습니다.\n불규칙 과거분사: hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\n스페인에서는 끝나지 않은 기간(hoy, esta semana)에 쓰고, 중남미에서는 단순 과거를 더 자주 씁니다.", ['열쇠를 잃어버렸어요.', '멕시코에 가 본 적 있어요?']),
 'lt': ('Būtasis atliktinis laikas (pretérito perfecto)', "haber esamuoju laiku + dalyvis: he, has, ha, hemos, habéis, han + hablado / comido / vivido. Dalyvis nekaitomas ir neatskiriamas nuo haber.\nNetaisyklingi dalyviai: hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\nIspanijoje vartojamas nepasibaigusiam laikotarpiui (hoy, esta semana); Lotynų Amerikoje dažnai keičiamas indefinido.", ['Pamečiau raktus.', 'Ar esi buvęs Meksikoje?']),
 'tl': ('Ang pretérito perfecto', "haber sa kasalukuyan + participle: he, has, ha, hemos, habéis, han + hablado / comido / vivido. Hindi nagbabago ang participle at hindi inihihiwalay sa haber.\nDi-regular na participle: hecho, dicho, visto, escrito, puesto, vuelto, abierto, muerto, roto.\nSa Espanya, ginagamit sa panahong hindi pa tapos (hoy, esta semana); sa Latin America, mas madalas ang pretérito.", ['Nawala ko ang mga susi.', 'Nakapunta ka na ba sa Mexico?']),
},
'futur-conditionnel': {
 'de': ('Futur und Konditional', "Futur: Infinitiv + é, ás, á, emos, éis, án (hablaré). Konditional: Infinitiv + ía, ías, ía, íamos, íais, ían (hablaría).\nBeide haben dieselben unregelmäßigen Stämme: tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\nDas Futur drückt auch eine Vermutung aus: Serán las diez (es wird wohl zehn Uhr sein).", ['Morgen wird es regnen.', 'Ich würde gern reisen.']),
 'it': ('Il futuro e il condizionale', "Futuro: infinito + é, ás, á, emos, éis, án (hablaré). Condizionale: infinito + ía, ías, ía, íamos, íais, ían (hablaría).\nStessi radicali irregolari per entrambi: tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\nIl futuro esprime anche una supposizione: Serán las diez (saranno le dieci).", ['Domani pioverà.', 'Mi piacerebbe viaggiare.']),
 'pt': ('O futuro e o condicional', "Futuro: infinitivo + é, ás, á, emos, éis, án (hablaré). Condicional: infinitivo + ía, ías, ía, íamos, íais, ían (hablaría).\nOs mesmos radicais irregulares para os dois: tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\nO futuro também exprime suposição: Serán las diez (devem ser dez horas).", ['Amanhã vai chover.', 'Eu gostaria de viajar.']),
 'ja': ('未来形と過去未来（条件法）', "未来形：不定詞 + é, ás, á, emos, éis, án（hablaré）。過去未来：不定詞 + ía, ías, ía, íamos, íais, ían（hablaría）。\n不規則な語幹は共通です：tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-。\n未来形は推量も表します：Serán las diez（10時ごろだろう）。", ['明日は雨が降るでしょう。', '旅行がしたいです。']),
 'zh': ('将来时与条件式', "将来时：不定式 + é, ás, á, emos, éis, án（hablaré）。条件式：不定式 + ía, ías, ía, íamos, íais, ían（hablaría）。\n两者的不规则词根相同：tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-。\n将来时也可表示推测：Serán las diez（大概十点了）。", ['明天会下雨。', '我想去旅行。']),
 'ko': ('미래형과 조건법', "미래형: 동사원형 + é, ás, á, emos, éis, án(hablaré). 조건법: 동사원형 + ía, ías, ía, íamos, íais, ían(hablaría).\n불규칙 어간은 둘 다 같습니다: tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\n미래형은 추측도 나타냅니다: Serán las diez(열 시쯤 됐을 거예요).", ['내일 비가 올 거예요.', '여행하고 싶어요.']),
 'lt': ('Būsimasis laikas ir tariamoji nuosaka', "Būsimasis: bendratis + é, ás, á, emos, éis, án (hablaré). Tariamoji: bendratis + ía, ías, ía, íamos, íais, ían (hablaría).\nAbiem tie patys netaisyklingi kamienai: tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\nBūsimasis laikas reiškia ir spėjimą: Serán las diez (turbūt dešimta valanda).", ['Rytoj lis.', 'Norėčiau keliauti.']),
 'tl': ('Hinaharap at kondisyonal', "Hinaharap: infinitive + é, ás, á, emos, éis, án (hablaré). Kondisyonal: infinitive + ía, ías, ía, íamos, íais, ían (hablaría).\nPareho ang mga di-regular na ugat: tendr-, pondr-, vendr-, saldr-, podr-, querr-, sabr-, har-, dir-, habr-.\nNagpapahayag din ng hula ang hinaharap: Serán las diez (siguro alas-diyes na).", ['Uulan bukas.', 'Gusto kong maglakbay.']),
},
'imperatif': {
 'de': ('Der Imperativ', "Bejahtes tú = 3. Person Präsens: habla, come, vive. Unregelmäßig: di, haz, ve, pon, sal, sé, ten, ven.\nUsted / ustedes und alle verneinten Formen nehmen den Subjuntivo: hable, no hables, no comas.\nPronomen werden an den bejahten Imperativ angehängt (dámelo) und stehen beim verneinten davor (no me lo des).", ['Komm her.', 'Mach dir keine Sorgen.']),
 'it': ("L'imperativo", "Tú affermativo = terza persona del presente: habla, come, vive. Irregolari: di, haz, ve, pon, sal, sé, ten, ven.\nUsted / ustedes e tutte le forme negative usano il congiuntivo: hable, no hables, no comas.\nI pronomi si attaccano all'affermativo (dámelo) e precedono il verbo al negativo (no me lo des).", ['Vieni qui.', 'Non preoccuparti.']),
 'pt': ('O imperativo', "Tú afirmativo = terceira pessoa do presente: habla, come, vive. Irregulares: di, haz, ve, pon, sal, sé, ten, ven.\nUsted / ustedes e todas as formas negativas usam o subjuntivo: hable, no hables, no comas.\nOs pronomes ligam-se ao afirmativo (dámelo) e vêm antes no negativo (no me lo des).", ['Venha aqui.', 'Não se preocupe.']),
 'ja': ('命令形', "tú の肯定命令は直説法現在の三人称単数と同じ：habla, come, vive。不規則：di, haz, ve, pon, sal, sé, ten, ven。\nusted / ustedes とすべての否定命令は接続法を使います：hable, no hables, no comas。\n代名詞は肯定命令ではうしろにつけ（dámelo）、否定命令では前に置きます（no me lo des）。", ['こっちに来て。', '心配しないで。']),
 'zh': ('命令式', "tú 的肯定命令 = 陈述式现在时第三人称单数：habla, come, vive。不规则：di, haz, ve, pon, sal, sé, ten, ven。\nusted / ustedes 以及所有否定命令用虚拟式：hable, no hables, no comas。\n代词在肯定命令中连写在后面（dámelo），在否定命令中放在前面（no me lo des）。", ['过来。', '别担心。']),
 'ko': ('명령형', "tú 긍정 명령 = 직설법 현재 3인칭 단수: habla, come, vive. 불규칙: di, haz, ve, pon, sal, sé, ten, ven.\nusted / ustedes와 모든 부정 명령은 접속법을 씁니다: hable, no hables, no comas.\n대명사는 긍정 명령 뒤에 붙이고(dámelo), 부정 명령에서는 앞에 둡니다(no me lo des).", ['이리 와.', '걱정하지 마.']),
 'lt': ('Liepiamoji nuosaka', "Teigiamas tú = esamojo laiko trečiasis asmuo: habla, come, vive. Netaisyklingi: di, haz, ve, pon, sal, sé, ten, ven.\nUsted / ustedes ir visos neigiamos formos vartoja subjuntivo: hable, no hables, no comas.\nĮvardžiai prijungiami prie teigiamos formos (dámelo) ir eina prieš neigiamą (no me lo des).", ['Ateik čia.', 'Nesijaudink.']),
 'tl': ('Ang pautos', "Apirmatibong tú = ikatlong panauhan ng kasalukuyan: habla, come, vive. Di-regular: di, haz, ve, pon, sal, sé, ten, ven.\nGumagamit ng subjuntivo ang usted / ustedes at lahat ng negatibo: hable, no hables, no comas.\nIdinidikit ang panghalip sa apirmatibo (dámelo) at inilalagay sa unahan sa negatibo (no me lo des).", ['Halika rito.', 'Huwag kang mag-alala.']),
},
'subjonctif': {
 'de': ('Der Subjuntivo im Präsens', "Bildung: von der 1. Person Präsens ausgehen und den Vokal tauschen. -ar → e (hable, hables, hable, hablemos, habléis, hablen); -er / -ir → a (coma, viva). Unregelmäßig: sea, esté, vaya, haya, sepa, dé; tenga, haga, diga, venga, pueda.\nGebrauch: Wunsch und Wille (Quiero que vengas), Gefühl (Me alegro de que estés aquí), Zweifel (No creo que sea verdad), nach para que, cuando mit Zukunftsbezug (Cuando llegues, llámame), ojalá.", ['Ich möchte, dass du mit mir kommst.', 'Ich hoffe, es geht dir gut.']),
 'it': ('Il congiuntivo presente', "Formazione: si parte dalla prima persona del presente e si scambia la vocale. -ar → e (hable, hables, hable, hablemos, habléis, hablen); -er / -ir → a (coma, viva). Irregolari: sea, esté, vaya, haya, sepa, dé; tenga, haga, diga, venga, pueda.\nUsi: desiderio e volontà (Quiero que vengas), emozione (Me alegro de que estés aquí), dubbio (No creo que sea verdad), dopo para que, cuando con valore futuro (Cuando llegues, llámame), ojalá.", ['Voglio che tu venga con me.', 'Spero che tu stia bene.']),
 'pt': ('O presente do subjuntivo', "Formação: parte-se da primeira pessoa do presente e troca-se a vogal. -ar → e (hable, hables, hable, hablemos, habléis, hablen); -er / -ir → a (coma, viva). Irregulares: sea, esté, vaya, haya, sepa, dé; tenga, haga, diga, venga, pueda.\nUsos: desejo e vontade (Quiero que vengas), emoção (Me alegro de que estés aquí), dúvida (No creo que sea verdad), depois de para que, cuando com valor de futuro (Cuando llegues, llámame — em português seria o futuro do subjuntivo), ojalá.", ['Quero que você venha comigo.', 'Espero que você esteja bem.']),
 'ja': ('接続法現在', "作り方：直説法現在の一人称単数から、母音を入れかえます。-ar → e（hable, hables, hable, hablemos, habléis, hablen）、-er / -ir → a（coma, viva）。不規則：sea, esté, vaya, haya, sepa, dé、tenga, haga, diga, venga, pueda。\n使い方：願望・意志（Quiero que vengas）、感情（Me alegro de que estés aquí）、疑い（No creo que sea verdad）、para que の後、未来のことを言う cuando の後（Cuando llegues, llámame）、ojalá。", ['いっしょに来てほしいです。', '元気だといいのですが。']),
 'zh': ('虚拟式现在时', "构成：从陈述式现在时第一人称单数出发，调换元音。-ar → e（hable, hables, hable, hablemos, habléis, hablen）；-er / -ir → a（coma, viva）。不规则：sea, esté, vaya, haya, sepa, dé；tenga, haga, diga, venga, pueda。\n用法：愿望和意志（Quiero que vengas），情感（Me alegro de que estés aquí），怀疑（No creo que sea verdad），para que 之后，表示将来的 cuando 之后（Cuando llegues, llámame），ojalá。", ['我希望你跟我一起来。', '希望你一切都好。']),
 'ko': ('접속법 현재', "만드는 법: 직설법 현재 1인칭 단수에서 모음을 바꿉니다. -ar → e(hable, hables, hable, hablemos, habléis, hablen), -er / -ir → a(coma, viva). 불규칙: sea, esté, vaya, haya, sepa, dé, tenga, haga, diga, venga, pueda.\n쓰임: 바람과 의지(Quiero que vengas), 감정(Me alegro de que estés aquí), 의심(No creo que sea verdad), para que 뒤, 미래를 나타내는 cuando 뒤(Cuando llegues, llámame), ojalá.", ['저와 같이 가 주면 좋겠어요.', '잘 지내길 바라요.']),
 'lt': ('Subjuntivo esamasis laikas', "Daroma iš esamojo laiko pirmojo asmens, sukeičiant balsį. -ar → e (hable, hables, hable, hablemos, habléis, hablen); -er / -ir → a (coma, viva). Netaisyklingi: sea, esté, vaya, haya, sepa, dé; tenga, haga, diga, venga, pueda.\nVartojimas: noras ir valia (Quiero que vengas), jausmas (Me alegro de que estés aquí), abejonė (No creo que sea verdad), po para que, po cuando ateities prasme (Cuando llegues, llámame), ojalá.", ['Noriu, kad eitum su manimi.', 'Tikiuosi, kad tau gerai sekasi.']),
 'tl': ('Ang subjuntivo sa kasalukuyan', "Pagbuo: mula sa unang panauhan ng kasalukuyan, papalitan ang patinig. -ar → e (hable, hables, hable, hablemos, habléis, hablen); -er / -ir → a (coma, viva). Di-regular: sea, esté, vaya, haya, sepa, dé; tenga, haga, diga, venga, pueda.\nGamit: hangarin at kagustuhan (Quiero que vengas), damdamin (Me alegro de que estés aquí), pag-aalinlangan (No creo que sea verdad), pagkatapos ng para que, cuando na tumutukoy sa hinaharap (Cuando llegues, llámame), ojalá.", ['Gusto kong sumama ka sa akin.', 'Sana ay mabuti ka.']),
},
'relatives-comparaison': {
 'de': ('Vergleichen und verbinden', "Komparativ: más … que, menos … que, tan … como (so … wie), tanto/a … como (so viel … wie). Unregelmäßig: mejor, peor, mayor, menor. Superlativ: el más alto de la clase; -ísimo (carísimo).\nRelativpronomen: que (am häufigsten), quien (Personen, nach Präposition), donde, lo que (was).", ['Er ist größer als ich.', 'Ich verstehe nicht, was du sagst.']),
 'it': ('Confrontare e collegare', "Comparativo: más … que, menos … que, tan … como (tanto … quanto), tanto/a … como. Irregolari: mejor, peor, mayor, menor. Superlativo: el más alto de la clase; -ísimo (carísimo).\nRelativi: que (il più comune), quien (persone, dopo preposizione), donde, lo que (ciò che).", ['È più alto di me.', 'Non capisco quello che dici.']),
 'pt': ('Comparar e ligar', "Comparativo: más … que, menos … que, tan … como (tão … quanto), tanto/a … como. Irregulares: mejor, peor, mayor, menor. Superlativo: el más alto de la clase; -ísimo (carísimo).\nRelativos: que (o mais comum), quien (pessoas, depois de preposição), donde, lo que (o que).", ['Ele é mais alto do que eu.', 'Não entendo o que você diz.']),
 'ja': ('比較と関係詞', "比較級：más … que（〜より…）、menos … que、tan … como（〜と同じくらい）、tanto/a … como。不規則：mejor, peor, mayor, menor。最上級：el más alto de la clase、-ísimo（carísimo）。\n関係詞：que（いちばんよく使う）、quien（人、前置詞の後）、donde、lo que（〜こと）。", ['彼は私より背が高いです。', 'あなたの言っていることがわかりません。']),
 'zh': ('比较与关系词', "比较级：más … que，menos … que，tan … como（和……一样），tanto/a … como。不规则：mejor, peor, mayor, menor。最高级：el más alto de la clase；-ísimo（carísimo）。\n关系词：que（最常用），quien（指人，用于介词后），donde，lo que（……的事）。", ['他比我高。', '我不明白你说的话。']),
 'ko': ('비교와 관계사', "비교급: más … que, menos … que, tan … como(~만큼), tanto/a … como. 불규칙: mejor, peor, mayor, menor. 최상급: el más alto de la clase, -ísimo(carísimo).\n관계사: que(가장 흔함), quien(사람, 전치사 뒤), donde, lo que(~하는 것).", ['그는 저보다 키가 커요.', '무슨 말인지 모르겠어요.']),
 'lt': ('Lyginimas ir jungimas', "Aukštesnysis laipsnis: más … que, menos … que, tan … como (toks pat … kaip), tanto/a … como. Netaisyklingi: mejor, peor, mayor, menor. Aukščiausiasis: el más alto de la clase; -ísimo (carísimo).\nSantykiniai žodžiai: que (dažniausias), quien (asmenims, po prielinksnio), donde, lo que (tai, ką).", ['Jis aukštesnis už mane.', 'Nesuprantu, ką sakai.']),
 'tl': ('Paghahambing at pag-uugnay', "Paghahambing: más … que, menos … que, tan … como (kasing-), tanto/a … como. Di-regular: mejor, peor, mayor, menor. Pinakamataas: el más alto de la clase; -ísimo (carísimo).\nMga pang-ugnay: que (pinakakaraniwan), quien (tao, pagkatapos ng pang-ukol), donde, lo que (ang).", ['Mas matangkad siya sa akin.', 'Hindi ko maintindihan ang sinasabi mo.']),
},
'subjonctif-imparfait': {
 'de': ('Der Subjuntivo Imperfekt und die Hypothese', "Gebildet aus der 3. Person Plural des Indefinido: hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran (oder -se: hablase). Tuvieron → tuviera, fueron → fuera.\nIrreale Bedingung: si + Subjuntivo Imperfekt, Konditional. Si tuviera dinero, viajaría.\nIrreale Vergangenheit: Si hubiera sabido, habría venido.\nNach „si“ nie Subjuntivo Präsens oder Konditional.", ['Wenn ich reich wäre, würde ich ein Haus kaufen.']),
 'it': ("Il congiuntivo imperfetto e l'ipotesi", "Si forma sulla terza persona plurale del passato remoto: hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran (o -se: hablase). Tuvieron → tuviera, fueron → fuera.\nIpotesi irreale: si + congiuntivo imperfetto, condizionale. Si tuviera dinero, viajaría.\nIrreale del passato: Si hubiera sabido, habría venido.\nMai congiuntivo presente né condizionale dopo «si».", ['Se fossi ricco, comprerei una casa.']),
 'pt': ('O imperfeito do subjuntivo e a hipótese', "Forma-se na terceira pessoa do plural do indefinido: hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran (ou -se: hablase). Tuvieron → tuviera, fueron → fuera.\nHipótese irreal: si + imperfeito do subjuntivo, condicional. Si tuviera dinero, viajaría.\nIrreal do passado: Si hubiera sabido, habría venido.\nNunca presente do subjuntivo nem condicional depois de «si».", ['Se eu fosse rico, compraria uma casa.']),
 'ja': ('接続法過去と仮定', "点過去の三人称複数から作ります：hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran（-se 形：hablase）。tuvieron → tuviera、fueron → fuera。\n現実に反する仮定：si + 接続法過去、過去未来。Si tuviera dinero, viajaría。\n過去の事実に反する仮定：Si hubiera sabido, habría venido。\nsi の後には接続法現在も過去未来も使いません。", ['お金持ちなら家を買うのに。']),
 'zh': ('虚拟式过去时与假设', "由简单过去时第三人称复数构成：hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran（或 -se 形式：hablase）。tuvieron → tuviera，fueron → fuera。\n与现在事实相反的假设：si + 虚拟式过去时，条件式。Si tuviera dinero, viajaría。\n与过去事实相反：Si hubiera sabido, habría venido。\nsi 之后不用虚拟式现在时，也不用条件式。", ['如果我有钱，我就买一栋房子。']),
 'ko': ('접속법 과거와 가정', "단순 과거 3인칭 복수에서 만듭니다: hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran(-se형: hablase). tuvieron → tuviera, fueron → fuera.\n현실과 반대되는 가정: si + 접속법 과거, 조건법. Si tuviera dinero, viajaría.\n과거 사실과 반대: Si hubiera sabido, habría venido.\nsi 뒤에는 접속법 현재도 조건법도 쓰지 않습니다.", ['부자라면 집을 살 텐데요.']),
 'lt': ('Subjuntivo būtasis ir prielaida', "Daromas iš indefinido daugiskaitos trečiojo asmens: hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran (arba -se: hablase). Tuvieron → tuviera, fueron → fuera.\nNereali sąlyga: si + subjuntivo būtasis, tariamoji nuosaka. Si tuviera dinero, viajaría.\nNereali praeitis: Si hubiera sabido, habría venido.\nPo „si“ niekada nevartojamas subjuntivo esamasis ar tariamoji nuosaka.", ['Jei būčiau turtingas, nusipirkčiau namą.']),
 'tl': ('Ang subjuntivo sa nakaraan at ang hinuha', "Binubuo mula sa ikatlong panauhang maramihan ng pretérito: hablaron → hablara, hablaras, hablara, habláramos, hablarais, hablaran (o -se: hablase). Tuvieron → tuviera, fueron → fuera.\nDi-totoong kondisyon: si + subjuntivo sa nakaraan, kondisyonal. Si tuviera dinero, viajaría.\nDi-totoo sa nakaraan: Si hubiera sabido, habría venido.\nHindi kailanman ginagamit ang subjuntivo sa kasalukuyan o kondisyonal pagkatapos ng «si».", ['Kung mayaman ako, bibili ako ng bahay.']),
},
'passif-se': {
 'de': ('Das Passiv und „se“', "Passiv: ser + angeglichenes Partizip + por. La casa fue construida por mi abuelo. Mündlich selten.\nMan bevorzugt „se“: Se habla español (man spricht Spanisch). Se venden pisos. Se dice que…\n„Se“ dient auch für reflexive Verben (levantarse) und Ungewolltes: Se me olvidó (ich habe es vergessen).", ['Hier spricht man Spanisch.', 'Mir ist das Glas heruntergefallen.']),
 'it': ('Il passivo e il «se»', "Passivo: ser + participio accordato + por. La casa fue construida por mi abuelo. Poco frequente nel parlato.\nSi preferisce «se», come il «si» italiano: Se habla español (si parla spagnolo). Se venden pisos. Se dice que…\n«Se» serve anche ai verbi riflessivi (levantarse) e all'involontario: Se me olvidó (mi sono dimenticato).", ['Qui si parla spagnolo.', 'Mi è caduto il bicchiere.']),
 'pt': ('A passiva e o «se»', "Passiva: ser + particípio concordado + por. La casa fue construida por mi abuelo. Pouco usada na fala.\nPrefere-se «se», como em português: Se habla español (fala-se espanhol). Se venden pisos. Se dice que…\n«Se» serve também para verbos pronominais (levantarse) e para o involuntário: Se me olvidó (esqueci).", ['Aqui se fala espanhol.', 'O copo caiu da minha mão.']),
 'ja': ('受動態と se', "受動態：ser + 性数一致した過去分詞 + por。La casa fue construida por mi abuelo。話し言葉ではあまり使いません。\nふつうは se を使います：Se habla español（スペイン語が話されている）。Se venden pisos. Se dice que…\nse は再帰動詞（levantarse）や「うっかり〜してしまった」にも使います：Se me olvidó（忘れてしまった）。", ['ここではスペイン語が話されています。', 'コップを落としてしまいました。']),
 'zh': ('被动语态与 se', "被动语态：ser + 性数一致的过去分词 + por。La casa fue construida por mi abuelo。口语中较少用。\n更常用 se：Se habla español（这里说西班牙语）。Se venden pisos. Se dice que…\nse 也用于自反动词（levantarse）和无意中发生的事：Se me olvidó（我忘了）。", ['这里说西班牙语。', '我的杯子掉了。']),
 'ko': ('수동태와 se', "수동태: ser + 성수 일치한 과거분사 + por. La casa fue construida por mi abuelo. 말할 때는 잘 쓰지 않습니다.\n보통 se를 씁니다: Se habla español(스페인어를 씁니다). Se venden pisos. Se dice que…\nse는 재귀 동사(levantarse)와 뜻하지 않은 일에도 씁니다: Se me olvidó(깜빡했어요).", ['여기서는 스페인어를 써요.', '컵을 떨어뜨렸어요.']),
 'lt': ('Neveikiamoji rūšis ir „se“', "Neveikiamoji: ser + suderintas dalyvis + por. La casa fue construida por mi abuelo. Šnekamojoje kalboje reta.\nDažniau vartojamas „se“: Se habla español (kalbama ispaniškai). Se venden pisos. Se dice que…\n„Se“ vartojamas ir sangrąžiniams veiksmažodžiams (levantarse) bei netyčiniam veiksmui: Se me olvidó (pamiršau).", ['Čia kalbama ispaniškai.', 'Man iškrito stiklinė.']),
 'tl': ('Ang balintiyak at «se»', "Balintiyak: ser + tumutugmang participle + por. La casa fue construida por mi abuelo. Bihira sa usapan.\nMas ginagamit ang «se»: Se habla español (Espanyol ang sinasalita). Se venden pisos. Se dice que…\nGinagamit din ang «se» sa pandiwang pabalik (levantarse) at sa di-sinasadya: Se me olvidó (nakalimutan ko).", ['Espanyol ang sinasalita rito.', 'Nabitawan ko ang baso.']),
},
}
